import { GoogleGenAI } from "@google/genai";

// getGeminiResponse handles the communication with the Gemini model.
export const getGeminiResponse = async (userPrompt: string) => {
  try {
    // CRITICAL: Always use the process.env.API_KEY directly and initialize a new instance for the call.
    // The API key is assumed to be pre-configured and accessible.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: `You are the Civil Agile Portal Assistant. You help users navigate a dashboard containing links to bulk civil engineering and infrastructure data for three regions: Salah Deen, Baghdad, and Thyqar. 
        - Salah Deen: General infrastructure data hub for northern regions.
        - Baghdad: Central metropolitan civil data.
        - Thyqar: Southern regional development data.
        Be professional, brief, and helpful. Focus on civil engineering context. If asked about technical issues, tell them to check their network connection or verify their Google account access for the site logs.`,
        temperature: 0.7,
      },
    });

    // Directly access the .text property of the GenerateContentResponse object.
    return response.text || "I'm sorry, I couldn't process that request.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "There was an error connecting to the AI service. Please try again later.";
  }
};

