                  href={section.link} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className={`inline-flex items-center gap-3 bg-gradient-to-br ${region.gradient} text-white px-8 py-4 rounded-2xl font-bold shadow-lg hover:scale-105 transition-transform whitespace-nowrap`}
