                  <span>Open Spreadsheet</span>
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/>
                  </svg>
                </a>
              </div>

              {/* Data Table */}
              <div className="overflow-x-auto rounded-2xl border border-gray-100 shadow-sm">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-gray-50">
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest border-b">Province</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest border-b">Ring</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest border-b">FDT Units</th>
                    </tr>
                  </thead>
