                    {section.data.map((item, idx) => (
                      <tr key={idx} className="hover:bg-blue-50/30 transition-colors">
                        <td className="px-6 py-6">
                          <span className="font-bold text-gray-800 text-base">{item.province}</span>
                        </td>
                        <td className="px-6 py-6">
                          <span className="inline-flex items-center px-3 py-1 bg-blue-100 text-blue-700 rounded-lg font-bold text-xs">
