import React, { useState } from 'react';
import RegionCard from './components/RegionCard.tsx';
import RegionDetail from './components/RegionDetail.tsx';
import AIChat from './components/AIChat.tsx';
import { REGIONS } from './constants.tsx';
import { Region } from './types.ts';

const App: React.FC = () => {
  const [selectedRegionId, setSelectedRegionId] = useState<string | null>(null);

  const selectedRegion = REGIONS.find(r => r.id === selectedRegionId);

  const handleRegionClick = (region: Region, e: React.MouseEvent) => {
    // Intercept specific regions for custom internal detail views
    const internalRegions = ['thyqar', 'salah-deen', 'baghdad'];
    if (internalRegions.includes(region.id)) {
      e.preventDefault();
      setSelectedRegionId(region.id);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
